const body = $input.first().json.body;
const score = (body.fraud_score * 100).toFixed(1);
const reasons = Array.isArray(body.reasons) ? body.reasons.join(', ') : body.reasons;

return [{
  json: {
    subject: `[FRAUD ALERT] ${body.severity.toUpperCase()} — Score ${score}% — User ${body.user_id}`,
    message: [
      `A ${body.severity} fraud alert has been triggered.`,
      ``,
      `Transaction ID : ${body.transaction_id}`,
      `User           : ${body.user_id}`,
      `Merchant       : ${body.merchant_id || 'N/A'}`,
      `Amount         : ${body.currency} ${body.amount}`,
      `Fraud Score    : ${score}%`,
      `Decision       : ${body.decision.toUpperCase()}`,
      `Reasons        : ${reasons}`,
      `Country        : ${body.country || 'N/A'}`,
      ``,
      `View details   : ${body.dashboard_url}`,
    ].join('\n'),
    severity: body.severity,
    transaction_id: body.transaction_id,
    fraud_score: body.fraud_score,
    user_id: body.user_id,
    decision: body.decision
  }
}];

const body = $input.first().json.body;
return [{
  json: {
    event_type: 'fraud_alert',
    transaction_id: body.transaction_id,
    user_id: body.user_id,
    fraud_score: body.fraud_score,
    severity: body.severity,
    decision: body.decision,
    reasons: body.reasons,
    timestamp: new Date().toISOString()
  }
}];
